mapper.select:
select t.status_cd statusCd,t.rdp_id rdpId,t.owner_id ownerId,t.ft_name ftName,t.payer_obj_name
payerObjName,t.owner_name ownerName,t.fee_name feeName,t.ft_id ftId,t.start_time startTime,t.end_time
endTime,t.rule_id ruleId,t.community_id communityId,t.payer_obj_id payerObjId,t.refund_amount refundAmount,
t.refund_order_id refundOrderId
from refund_deposit_pre t
where 1 =1

    and t.status_cd= #{statusCd}


    and t.rdp_id= #{rdpId}


    and t.owner_id= #{ownerId}


    and t.ft_name= #{ftName}


    and t.payer_obj_name= #{payerObjName}


    and t.owner_name= #{ownerName}


    and t.fee_name= #{feeName}


    and t.ft_id= #{ftId}


    and t.start_time= #{startTime}


    and t.end_time= #{endTime}


    and t.rule_id= #{ruleId}


    and t.community_id= #{communityId}


    and t.payer_obj_id= #{payerObjId}


    and t.refund_order_id= #{refundOrderId}


    and t.refund_amount= #{refundAmount}

order by t.create_time desc

    limit #{page}, #{row}

